struct RandomAccessTag {};
struct InputTag {}; // Used for generic/slow path

template <typename I> struct IteratorTraits {
    using iterator_category = typename I::category;
};

// Optimization: Random Access (O(1))
template <typename I, typename D>
void advance_impl(I& i, D n, RandomAccessTag) {
    i += n;
}

// Fallback: Input/Forward (O(N))
template <typename I, typename D>
void advance_impl(I& i, D n, InputTag) {
    while (n-- > 0) ++i;
}

// Public API utilizing Tag Dispatch
template <typename I, typename D>
void advance(I& i, D n) {
    using Cat = typename IteratorTraits<I>::iterator_category;
    advance_impl(i, n, Cat{}); // Compile-time selection
}
